/**
 * strategies/team3Reversal/team3ReversalConfig.ts
 *
 * Every setting of Team 3 Reversal (VERSION 3): the VWAP-reversion baseline's
 * knobs, its caps, and one on/off switch per entry filter. With every switch
 * off the strategy is the baseline (docs/team3/components/baseline.md).
 *
 * Only what the strategy calculates on the minute bars lives here. Costs,
 * capital and fill timing belong to the platform: see contract/protocol.ts.
 *
 * Owner: team lead. Teammates read their own knob here but do not edit this file.
 */

import { newId } from "../../utils/ids";
import type { BaseStrategyConfig } from "../../types/strategy";
import { TEAM3_FILTERS, type FilterSet } from "./filters";
import { TEAM3_PROTOCOL } from "./contract/protocol";

export interface Team3ReversalConfig extends BaseStrategyConfig {
  type: "team3_reversal";

  // ---- Baseline: entry ------------------------------------------------
  /** Fade only when the close is at least this many VWAP sigmas from VWAP, on the side of the move. */
  entryZ: number;
  /** ...and the distance back to VWAP is at least this many bps of price (must beat round-trip costs). */
  minEdgeBps: number;

  // ---- Baseline: exit (target = back to VWAP, always on) ---------------
  /** Stop out when the close stretches this many sigmas against us. Must be > entryZ. */
  stopZ: number;
  /** Close after this many session bars held, whatever the price. */
  maxHoldBars: number;

  // ---- Baseline: session window -----------------------------------------
  /** No entries in the first N minutes after 9:30 ET (VWAP and sigma warm up). */
  skipOpenMinutes: number;
  /** No new entries in the last N minutes before 16:00 ET. */
  lastEntryMinutesBeforeClose: number;
  /** Close everything in the last N minutes before 16:00 ET. Never held overnight. */
  flattenMinutesBeforeClose: number;

  // ---- Baseline: size and caps ------------------------------------------
  /** Dollars per new entry (fixed-notional sizing). maxPositionSizeUsd (base field) caps one symbol. */
  tradeUsd: number;
  /** Cap on Team 3's gross exposure: sum of |shares| x price over all symbols, shorts included. */
  maxGrossUsd: number;
  /** How many of today's earlier session bars the filters and vol sizing look back on. */
  lookbackBars: number;

  // ---- Switches: one per component (all false = baseline) ---------------
  useVwapRegime: boolean;
  useVolume: boolean;
  useRelativeToSpy: boolean;
  /** Size each entry by volatility (riskPerTradeUsd) instead of tradeUsd. Still capped. */
  useVolSizing: boolean;
  /** costGate (R3): enter only if captureShare x edge to VWAP (bps) beats the round-trip cost (bps). */
  useCostGate: boolean;

  // ---- Knobs: the number each component is tuned by ---------------------
  /** vwapRegime: fewest VWAP side-switches in the window to count the day as choppy. */
  minVwapCrossings: number;
  /** vwapRegime: how many recent session bars to count crossings over. */
  vwapWindowBars: number;
  /** volume: skip bars whose volume is more than this many times the recent average. */
  volumeMaxRatio: number;
  /** relativeToSpy: the market symbol to compare against. Must be in `symbols`. */
  benchmarkSymbol: string;
  /** costGate: share of the stretch back to VWAP we expect to capture (0-1]. */
  captureShare: number;
  /** costGate: price-independent part of a round trip, bps: 2 x (slippage 5 + half spread 2), as in the protocol. */
  costFixedBps: number;
  /** costGate: commission per share, both legs counted, turned into bps at the entry price. */
  costCommissionPerShare: number;
  // ==== Stage 2 per-goal blocks (fields): each session adds lines ONLY between its own markers ====
  // ---- R1 (team3/r1) ----
  // ---- end R1 ----
  // ---- R2 (team3/r2) ----
  // ---- end R2 ----
  // ---- R4 (team3/r4) ----
  // ---- end R4 ----
  // ---- R5 (team3/r5) ----
  // ---- end R5 ----
  // ---- RSPY (team3/rspy) ----
  // ---- end RSPY ----
  /** volSizing: dollars a typical 1-minute move may cost per entry. 5 keeps most sizes inside the $ caps (25 hit the cap almost always). */
  riskPerTradeUsd: number;
}

export const DEFAULT_TEAM3_REVERSAL_SYMBOLS = [
  "SPY", "QQQ", "NVDA", "AAPL", "MSFT", "MU", "AMD", "AMZN", "META", "GOOGL", "TSLA",
];

export const DEFAULT_TEAM3_REVERSAL_CONFIG: Omit<Team3ReversalConfig, "id" | "symbols"> = {
  name: "Team 3 Reversal",
  type: "team3_reversal",
  // Shared config contract. maxPositionSizeUsd IS used (per-symbol cap); the other two are ignored.
  rollingWindowMs: 60_000,
  maxPositionSizeUsd: 10_000,
  cooldownMs: 0,
  enabled: true,

  entryZ: 2,
  minEdgeBps: 15,
  stopZ: 3.5,
  maxHoldBars: 30,
  skipOpenMinutes: 15,
  lastEntryMinutesBeforeClose: 15,
  flattenMinutesBeforeClose: 5,
  tradeUsd: 5_000,
  maxGrossUsd: 40_000,
  lookbackBars: 30,

  useVwapRegime: false,
  useVolume: false,
  useRelativeToSpy: false,
  useVolSizing: false,
  useCostGate: false,

  minVwapCrossings: 4,
  vwapWindowBars: 60,
  volumeMaxRatio: 3,
  benchmarkSymbol: "SPY",
  riskPerTradeUsd: 5,
  captureShare: 0.5,
  costFixedBps: 14,
  costCommissionPerShare: 0.005,
  // ==== Stage 2 per-goal blocks (defaults): each session adds lines ONLY between its own markers ====
  // ---- R1 (team3/r1) ----
  // ---- end R1 ----
  // ---- R2 (team3/r2) ----
  // ---- end R2 ----
  // ---- R4 (team3/r4) ----
  // ---- end R4 ----
  // ---- R5 (team3/r5) ----
  // ---- end R5 ----
  // ---- RSPY (team3/rspy) ----
  // ---- end RSPY ----
};

/** Merges defaults with overrides; a new ID is assigned unless one is given. */
export function createTeam3ReversalConfig(overrides: Partial<Team3ReversalConfig> = {}): Team3ReversalConfig {
  return {
    ...DEFAULT_TEAM3_REVERSAL_CONFIG,
    id: newId(),
    symbols: [...DEFAULT_TEAM3_REVERSAL_SYMBOLS],
    ...overrides,
  };
}

const fail = (message: string): never => { throw new Error(`team3_reversal: ${message}`); };
const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
const positiveInt = (v: number, name: string) => { if (!Number.isInteger(v) || v <= 0) fail(`${name} must be a positive whole number (got ${v})`); };
const wholeAtLeast0 = (v: number, name: string) => { if (!Number.isInteger(v) || v < 0) fail(`${name} must be a whole number >= 0 (got ${v})`); };
const positive = (v: number, name: string) => { if (!isNum(v) || v <= 0) fail(`${name} must be a positive number (got ${v})`); };
const atLeast0 = (v: number, name: string) => { if (!isNum(v) || v < 0) fail(`${name} must be a number >= 0 (got ${v})`); };

/** Throws on a config the strategy cannot trade safely, so a bad one fails when saved, not mid-run. */
export function validateTeam3ReversalConfig(c: Team3ReversalConfig, filters: FilterSet = TEAM3_FILTERS): void {
  // Symbols
  if (!Array.isArray(c.symbols) || c.symbols.length === 0) fail("symbols must be a non-empty list");
  if (c.symbols.some((s) => typeof s !== "string" || s.trim() === "")) fail("every symbol must be a non-empty ticker");

  // Entry and exit
  positive(c.entryZ, "entryZ");
  atLeast0(c.minEdgeBps, "minEdgeBps");
  positive(c.stopZ, "stopZ");
  if (c.stopZ <= c.entryZ) fail(`stopZ must be greater than entryZ (got ${c.stopZ} <= ${c.entryZ})`);
  positiveInt(c.maxHoldBars, "maxHoldBars");
  if (!(c.captureShare > 0 && c.captureShare <= 1)) fail(`captureShare must be in (0, 1] (got ${c.captureShare})`);
  atLeast0(c.costFixedBps, "costFixedBps");
  atLeast0(c.costCommissionPerShare, "costCommissionPerShare");
  // ==== Stage 2 per-goal blocks (validation): each session adds lines ONLY between its own markers ====
  // ---- R1 (team3/r1) ----
  // ---- end R1 ----
  // ---- R2 (team3/r2) ----
  // ---- end R2 ----
  // ---- R4 (team3/r4) ----
  // ---- end R4 ----
  // ---- R5 (team3/r5) ----
  // ---- end R5 ----
  // ---- RSPY (team3/rspy) ----
  // ---- end RSPY ----

  // Session window: 390 minutes in a session
  wholeAtLeast0(c.skipOpenMinutes, "skipOpenMinutes");
  positiveInt(c.flattenMinutesBeforeClose, "flattenMinutesBeforeClose");
  wholeAtLeast0(c.lastEntryMinutesBeforeClose, "lastEntryMinutesBeforeClose");
  if (c.lastEntryMinutesBeforeClose < c.flattenMinutesBeforeClose) fail("lastEntryMinutesBeforeClose must be >= flattenMinutesBeforeClose");
  if (c.skipOpenMinutes + c.lastEntryMinutesBeforeClose >= 390) fail("skipOpenMinutes + lastEntryMinutesBeforeClose leaves no time to trade");

  // Size and caps: trade <= symbol cap <= gross cap <= what the protocol's engine allows
  positive(c.tradeUsd, "tradeUsd");
  positive(c.maxPositionSizeUsd, "maxPositionSizeUsd");
  positive(c.maxGrossUsd, "maxGrossUsd");
  if (c.tradeUsd > c.maxPositionSizeUsd) fail("tradeUsd must be <= maxPositionSizeUsd");
  if (c.maxPositionSizeUsd > c.maxGrossUsd) fail("maxPositionSizeUsd must be <= maxGrossUsd");
  const engine = TEAM3_PROTOCOL.riskConfig;
  if (c.maxPositionSizeUsd > engine.maxPositionSizeUsd) fail(`maxPositionSizeUsd must be <= the protocol's engine cap ${engine.maxPositionSizeUsd}`);
  if (c.maxGrossUsd > engine.maxNotionalExposureUsd) fail(`maxGrossUsd must be <= the protocol's engine cap ${engine.maxNotionalExposureUsd}`);
  positiveInt(c.lookbackBars, "lookbackBars");

  // Component knobs
  positiveInt(c.minVwapCrossings, "minVwapCrossings");
  if (!Number.isInteger(c.vwapWindowBars) || c.vwapWindowBars < 2 || c.vwapWindowBars > 390) {
    fail(`vwapWindowBars must be a whole number from 2 to 390 (got ${c.vwapWindowBars})`);
  }
  positive(c.volumeMaxRatio, "volumeMaxRatio");
  positive(c.riskPerTradeUsd, "riskPerTradeUsd");
  if (c.useVolSizing && c.lookbackBars < 5) fail(`useVolSizing needs lookbackBars >= 5 to measure volatility (got ${c.lookbackBars})`);
  if (c.useRelativeToSpy && !c.symbols.includes(c.benchmarkSymbol)) {
    // The strategy only receives bars for its own symbols, so it could never see the benchmark.
    fail(`useRelativeToSpy needs ${c.benchmarkSymbol} in symbols to read its bars`);
  }

  // A filter still marked "stub" would silently be the baseline under its name.
  for (const f of filters.entry) {
    if (c[f.switchKey] && f.status === "stub") fail(`${f.switchKey} is on but filter "${f.name}" is still a stub`);
  }
}
